INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-4', 'Partir a loiça toda', 'partir a loica toda', 'Ter um desempenho que impressiona toda a gente.', 'To bring the house down', 'To break all the crockery', '[]', 'Neste sentido positivo. Também pode significar causar confusão ou agir de forma explosiva; nesse contexto, «to raise hell» é uma aproximação.', '', '[]', '', '', 0, 3, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-5', 'Ir com os porcos', 'ir com os porcos', 'Perder-se, estragar-se ou falhar.', 'To go down the drain', 'To go with the pigs', '[]', 'Para algo que se perde. Quando se refere a morrer, «to kick the bucket» é um equivalente informal.', '', '[]', '', '', 0, 4, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
