INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-33', 'Pensar na morte da bezerra', 'pensar na morte da bezerra', 'Estar distraído, alheado do que se passa.', 'To be away with the fairies', 'To think about the death of the female calf', '[]', 'O equivalente inglês é informal.', '', '[]', '', '', 0, 32, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
