INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-38', 'Quem não tem cão, caça com gato', 'quem nao tem cao caca com gato', 'Desenrascar-se com os meios disponíveis.', 'To make the best of a bad job', 'Those who don''t have a dog hunt with a cat', '[]', 'Aproximação: aproveitar o que se tem, mesmo que não seja o ideal.', '', '[]', '', '', 0, 37, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-39', 'À grande e à francesa', 'a grande e a francesa', 'Viver ou fazer algo com luxo e abundância.', 'To live the life of Riley', 'On a grand scale and in the French manner', '[]', 'O equivalente inglês realça uma vida confortável e despreocupada.', '', '[]', '', '', 0, 38, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-40', 'Línguas de perguntador', 'linguas de perguntador', 'Resposta brincalhona para não satisfazer uma pergunta curiosa.', 'Ask no questions and you''ll be told no lies', 'Questioners'' tongues', '[]', 'Equivalente funcional aproximado: não designa comida nem traduz a imagem portuguesa.', 'https://web.letras.up.pt/ftopa/Artigos%20em%20revistas/Na%20ponta%20da%20l%C3%ADngua.pdf', '[]', '', '', 0, 39, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-41', 'A pensar morreu um burro', 'a pensar morreu um burro', 'Dizer a alguém para deixar de hesitar e passar à ação.', 'He who hesitates is lost', 'A donkey died thinking', '[]', 'Equivalente aproximado, usado como provérbio.', 'https://cvc.cervantes.es/lengua/refranero/Ficha.aspx?Lng=6&Par=59093', '[]', '', '', 0, 40, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-42', 'É canja!', 'e canja', 'É muito fácil.', 'It''s a piece of cake!', 'It''s chicken soup!', '[]', '', '', '[]', '', '', 0, 41, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-43', 'Grão a grão enche a galinha o papo', 'grao a grao enche a galinha o papo', 'Pequenas quantidades ou esforços acabam por produzir um grande resultado.', 'Many a little makes a mickle', 'Grain by grain, the hen fills its crop', '[]', 'Provérbio inglês tradicional. Na linguagem corrente, «every little helps» transmite a mesma ideia.', '', '[]', '', '', 0, 42, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-44', 'Com uma perna às costas', 'com uma perna as costas', 'Fazer algo com muita facilidade.', 'With one hand tied behind your back', 'With one leg behind your back', '[]', '', '', '[]', '', '', 0, 43, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-45', 'Feito ao bife', 'feito ao bife', 'Estar em apuros, sem uma boa saída.', 'Your goose is cooked', 'Done like a steak', '[]', '', '', '[]', '', '', 0, 44, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-46', 'Abanar o capacete', 'abanar o capacete', 'Dançar.', 'To shake a leg', 'To shake the helmet', '[]', 'No sentido de dançar. Em inglês, «shake a leg» também pode querer dizer «despacha-te».', '', '[]', '', '', 0, 45, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-47', 'Rés-vés Campo de Ourique', 'res ves campo de ourique', 'Por muito pouco; à justa.', 'By the skin of your teeth', 'Just skimming Campo de Ourique', '[]', 'O equivalente aplica-se sobretudo a conseguir algo ou escapar por muito pouco.', '', '[]', '', '', 0, 46, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-48', 'Meter a pata na poça', 'meter a pata na poca', 'Dizer ou fazer algo inconveniente por engano.', 'To put your foot in it', 'To put your paw in the puddle', '[]', '', '', '[]', '', '', 0, 47, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-49', 'Soltar a franga', 'soltar a franga', 'Descontrair-se e divertir-se sem inibições.', 'To let your hair down', 'To let the young hen loose', '[]', '', '', '[]', '', '', 0, 48, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-50', 'Mais vale um pássaro na mão que dois a voar', 'mais vale um passaro na mao que dois a voar', 'É preferível uma vantagem certa a uma possibilidade incerta.', 'A bird in the hand is worth two in the bush', 'A bird in the hand is worth more than two flying', '[]', '', '', '[]', '', '', 0, 49, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-51', 'Más línguas', 'mas linguas', 'Pessoas que fazem comentários maldosos ou espalham rumores.', 'The rumour mill', 'Bad tongues', '[]', 'Aproximação: a expressão inglesa designa a circulação de rumores, não propriamente as pessoas.', '', '[]', '', '', 0, 50, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO expressions (id, expression, normalized, meaning_pt, meaning_en, literal_en, examples, notes, source_url, tags, image_url, image_alt, published, sort_order, created_at, updated_at) VALUES ('original-52', 'Filho de peixe sabe nadar', 'filho de peixe sabe nadar', 'Os filhos tendem a ter características ou aptidões semelhantes às dos pais.', 'The apple doesn''t fall far from the tree', 'A fish''s child knows how to swim', '[]', '', '', '[]', '', '', 0, 51, '2026-10-13T00:00:00.000Z', '2026-10-13T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
